$fs = New-Object System.IO.FileStream("C:\Program Files\Private Internet Access\data\log.bin","Open","Read","ReadWrite"); $ms=New-Object System.IO.MemoryStream; $fs.CopyTo($ms); $fs.Dispose(); $b=$ms.ToArray(); $rec=520;
function RecTime($i){ $off=$i*$rec; $v=[BitConverter]::ToInt64($b,$off+8); [datetimeoffset]::FromUnixTimeMilliseconds(0) };
foreach($i in @(0, 500, 1000, 1500, 2040, 2046, 2047)) { $off=$i*$rec; $lo=[BitConverter]::ToUInt32($b,$off+8); $hi=[BitConverter]::ToUInt32($b,$off+12); $v=[BitConverter]::ToInt64($b,$off+8); "rec $i : raw=0x$($hi.ToString('X8'))$($lo.ToString('X8')) int64=$v" }

$fs = New-Object System.IO.FileStream("C:\Program Files\Private Internet Access\data\log.bin","Open","Read","ReadWrite"); $ms=New-Object System.IO.MemoryStream; $fs.CopyTo($ms); $fs.Dispose(); $b=$ms.ToArray(); $rec=520;
$times=@(); for($i=0;$i -lt 2048;$i++){ $off=$i*$rec; $v=[BitConverter]::ToInt64($b,$off+8)/1e9; $times += $v }
$sorted = $times | Sort-Object; "span: $((Get-Date).AddSeconds($sorted[0]- (Get-Date).ToUniversalTime().AddSeconds(0).ToUnixTimeSeconds()))";
$epoch=[DateTimeOffset]::FromUnixTimeSeconds(0);
"first: $($epoch.AddSeconds($sorted[0]).LocalDateTime)"; "last: $($epoch.AddSeconds($sorted[-1]).LocalDateTime)";
$maxgap=0; $gapat=0; for($i=1;$i -lt $sorted.Count;$i++){ $g=$sorted[$i]-$sorted[$i-1]; if($g -gt $maxgap){ $maxgap=$g; $gapat=$sorted[$i-1] } }
"max gap: $([math]::Round($maxgap,1)) s starting $($epoch.AddSeconds($gapat).LocalDateTime)";
$gaps = @(); for($i=1;$i -lt $sorted.Count;$i++){ $g=$sorted[$i]-$sorted[$i-1]; if($g -gt 120){ $gaps += [pscustomobject]@{At=$epoch.AddSeconds($sorted[$i-1]).LocalDateTime; GapSec=[math]::Round($g,1)} } }; $gaps | Format-Table -AutoSize
